#include <iostream>
#include <vector>
#include <utility>
#include <algorithm>
#include <climits>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> grid(n, vector<int>(m));
    vector<pair<int, int>> pos[20001]; // Since n*m can be up to 80*80=6400, so max pair number is 3200, but using 20001 to be safe

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> grid[i][j];
            pos[grid[i][j]].push_back(make_pair(i, j));
        }
    }

    // For each pair, compute the minimal moves required
    int total = 0;
    for (int k = 1; k <= n*m/2; k++) {
        if (pos[k].size() != 2) continue;
        int x1 = pos[k][0].first, y1 = pos[k][0].second;
        int x2 = pos[k][1].first, y2 = pos[k][1].second;
        // Check if already adjacent
        if (abs(x1 - x2) + abs(y1 - y2) == 1) {
            continue;
        }
        // Find the minimal moves to make them adjacent
        // Try all possible adjacent positions for the first shoe, and see if the second can be placed adjacent
        int min_moves = INT_MAX;
        // For each possible target adjacent pair, compute the cost
        // The cost is 0 if both are already in the target positions, 1 if one is, 2 if none
        // We need to find the best target pair (a,b) adjacent, such that moving the two shoes to a and b costs minimal
        // Iterate over all possible adjacent pairs in the grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Check right neighbor
                if (j + 1 < m) {
                    int a = i, b = j;
                    int c = i, d = j+1;
                    // Check if current pair can be moved to (a,b) and (c,d)
                    int cost = 0;
                    if (grid[a][b] != k) cost++;
                    if (grid[c][d] != k) cost++;
                    // Also check the reverse: (c,d) and (a,b)
                    int cost_rev = 0;
                    if (grid[c][d] != k) cost_rev++;
                    if (grid[a][b] != k) cost_rev++;
                    min_moves = min(min_moves, min(cost, cost_rev));
                }
                // Check down neighbor
                if (i + 1 < n) {
                    int a = i, b = j;
                    int c = i+1, d = j;
                    int cost = 0;
                    if (grid[a][b] != k) cost++;
                    if (grid[c][d] != k) cost++;
                    int cost_rev = 0;
                    if (grid[c][d] != k) cost_rev++;
                    if (grid[a][b] != k) cost_rev++;
                    min_moves = min(min_moves, min(cost, cost_rev));
                }
            }
        }
        // The minimal moves for this pair is min_moves, but since each move swaps two shoes, the actual moves might be different
        // However, since we need to count the number of shoes moved, each swap moves two shoes
        // But the problem asks for the number of shoes to move, not swaps
        // So if min_moves is 0, no moves needed
        // If min_moves is 1, one shoe needs to move (but that's impossible as we need to swap)
        // Wait, the problem allows moving any shoe to any position, not just swaps
        // So the minimal number of shoes to move for this pair is min_moves
        // Because if both are not in the target positions, we need to move both (2 moves)
        // If one is in the target, we need to move one (1 move)
        // If both are in the target, 0 moves
        total += min_moves;
    }

    cout << total << endl;
    return 0;
}
```

### Explanation
1. **Reading Input**: The grid dimensions and the grid itself are read. Each shoe's positions are stored in an array of pairs.
2. **Checking Adjacent Pairs**: For each pair of shoes, we check if they are already adjacent. If they are, no moves are needed.
3. **Calculating Moves**: For each pair that is not adjacent, we check all possible adjacent cell pairs in the grid. For each possible target pair, we calculate the number of shoes that need to be moved. The minimal number of moves for each pair is added to the total.
4. **Output**: The total number of moves required is printed.

This approach ensures that we efficiently determine the minimal moves by considering all possible valid positions for each pair of shoes.

