#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
using namespace std;

const int MAXN = 85;
const int MAXM = 85;
const int MAXNUM = MAXN * MAXM;

int n, m;
int grid[MAXN][MAXM];
int pos[MAXNUM][2]; // pos[x] = {i, j} for each shoe number x
int pair_id[MAXN][MAXM]; // pair_id[i][j] = the other cell of the pair
bool visited[MAXN][MAXM];

int dx[4] = {0, 0, 1, -1};
int dy[4] = {1, -1, 0, 0};

bool bfs(int si, int sj, int ei, int ej) {
    memset(visited, 0, sizeof(visited));
    queue<pair<int, int>> q;
    q.push({si, sj});
    visited[si][sj] = true;

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        if (x == ei && y == ej) return true;

        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];

            if (nx >= 0 && nx < n && ny >= 0 && ny < m && !visited[nx][ny]) {
                visited[nx][ny] = true;
                q.push({nx, ny});
            }
        }
    }
    return false;
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> grid[i][j];
            pos[grid[i][j]][(pos[grid[i][j]][0] == 0 && pos[grid[i][j]][1] == 0) ? 0 : 1] = i * m + j + 1;
        }
    }

    // Build pair_id: for each cell, find its pair's cell
    for (int x = 1; x <= n * m / 2; x++) {
        int i1 = (pos[x][0] - 1) / m;
        int j1 = (pos[x][0] - 1) % m;
        int i2 = (pos[x][1] - 1) / m;
        int j2 = (pos[x][1] - 1) % m;
        pair_id[i1][j1] = pos[x][1];
        pair_id[i2][j2] = pos[x][0];
    }

    int ans = 0;
    memset(visited, 0, sizeof(visited));

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (visited[i][j]) continue;

            int other = pair_id[i][j];
            int oi = (other - 1) / m;
            int oj = (other - 1) % m;

            if (abs(i - oi) + abs(j - oj) == 1) {
                visited[i][j] = true;
                visited[oi][oj] = true;
                continue;
            }

            // Need to move one shoe
            visited[i][j] = true;
            visited[oi][oj] = true;
            ans++;
        }
    }

    cout << ans << endl;
    return 0;
}
