    }

    int total_pairs = (n * m) / 2;

    // Assign IDs: source=0, sink=1, cells start from 2
    int source = 0, sink = 1;
    int cell_id = 2;
    vector<vector<int>> id(n, vector<int>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            id[i][j] = cell_id++;
        }
    }

    // Bipartition: black (i+j even) connected to source, white to sink
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if ((i + j) % 2 == 0) {
                add_edge(source, id[i][j], 1, 0);
            } else {
                add_edge(id[i][j], sink, 1, 0);
            }
        }
    }

    // Add edges between adjacent cells
    vector<pair<int, int>> dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            for (auto &d : dirs) {
                int ni = i + d.first, nj = j + d.second;
                if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
                    if ((i + j) % 2 == 0) { // black to white
                        int cost = (grid[i][j] == grid[ni][nj]) ? -1 : 0;
                        add_edge(id[i][j], id[ni][nj], 1, cost);
                    }
                }
            }
        }
    }

    // Compute min cost flow of value total_pairs
    int cost = min_cost_flow(source, sink, total_pairs);
    if (cost == -1) {
        cout << -1 << endl;
    } else {
        cout << total_pairs + cost << endl;
    }

    return 0;
}
