To solve this problem, we need to determine the minimum number of shoes that need to be moved to make all pairs of shoes in the dressing room lie adjacent to each other. Each pair of shoes must be placed in adjacent cells (horizontally or vertically).

### Approach
1. **Problem Analysis**: The problem requires us to rearrange shoes such that each pair of shoes is adjacent. The key insight is that each move involves swapping two shoes, and we need to find the minimum number of such swaps.
2. **Graph Representation**: Represent the problem as a graph where each cell is a node. Edges exist between adjacent cells. Each pair of shoes must be placed on an edge (two adjacent cells).
3. **Bipartite Matching**: Use bipartite matching to find the maximum number of pairs that can be placed in adjacent cells without moving them. The minimum number of moves required will be the total number of pairs minus the maximum matching found.
4. **Algorithm**: 
   - Identify all pairs of shoes and their positions.
   - For each pair, check if they are already adjacent. If they are, count them as already correctly placed.
   - Use a bipartite graph to find the maximum matching where each node on one side represents a shoe and edges represent valid adjacent positions for another shoe.
   - The result is the total number of pairs minus the maximum matching.

### Solution Code
```cpp
#include <iostream>
#include <vector>
#include <cstring>
using namespace std;

const int MAX = 80 * 80 + 10;
int n, m;
int grid[80][80];
vector<pair<int, int>> pos[MAX]; // positions of each pair
int pair_id[80][80]; // which pair is at (i,j)
int pair_count;
int match_to[MAX]; // for bipartite matching
bool visited[MAX];

bool dfs(int u, vector<vector<int>>& adj) {
    for (int v : adj[u]) {
        if (!visited[v]) {
            visited[v] = true;
            if (match_to[v] == -1 || dfs(match_to[v], adj)) {
                match_to[v] = u;
                return true;
            }
        }
    }
    return false;
}

int bpm(const vector<vector<int>>& adj) {
    memset(match_to, -1, sizeof(match_to));
    int result = 0;
    for (int u = 0; u < adj.size(); u++) {
        memset(visited, false, sizeof(visited));
        if (dfs(u, adj)) result++;
    }
    return result;
}

int main() {
    cin >> n >> m;
    pair_count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> grid[i][j];
            if (grid[i][j] > pair_count) pair_count = grid[i][j];
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            pos[grid[i][j]].push_back({i, j});
        }
    }
    vector<vector<int>> adj(pair_count + 1);
    for (int p = 1; p <= pair_count; p++) {
        auto& cells = pos[p];
        for (int i = 0; i < cells.size(); i++) {
            int x1 = cells[i].first, y1 = cells[i].second;
            for (int j = 0; j < cells.size(); j++) {
                if (i == j) continue;
                int x2 = cells[j].first, y2 = cells[j].second;
                if (abs(x1 - x2) + abs(y1 - y2) == 1) {
                    adj[p].push_back(p);
                    break;
                }
            }
        }
    }
    int already = 0;
    for (int p = 1; p <= pair_count; p++) {
        auto& cells = pos[p];
        if (cells.size() != 2) continue;
        int x1 = cells[0].first, y1 = cells[0].second;
        int x2 = cells[1].first, y2 = cells[1].second;
        if (abs(x1 - x2) + abs(y1 - y2) == 1) already++;
    }
    vector<vector<int>> adj2(pair_count + 1);
    for (int p = 1; p <= pair_count; p++) {
        auto& cells = pos[p];
        for (int i = 0; i < cells.size(); i++) {
            int x1 = cells[i].first, y1 = cells[i].second;
            for (int j = 0; j < cells.size(); j++) {
                if (i == j) continue;
                int x2 = cells[j].first, y2 = cells[j].second;
                if (abs(x1 - x2) + abs(y1 - y2) == 1) {
                    adj2[p].push_back(p);
                    break;
                }
            }
        }
    }
    int max_match = bpm(adj2);
    cout << pair_count - already - max_match << endl;
    return 0;
}
