To solve this problem, we need to determine the minimum number of shoe movements required to make all pairs of shoes in a dressing room lie adjacent to each other. Each pair of shoes has a unique number, and the goal is to ensure that each pair is placed in adjacent cells (either horizontally or vertically).

### Approach
1. **Problem Analysis**: 
   - The dressing room is represented as an `n x m` grid where each cell contains a shoe.
   - Each shoe pair has a unique number from 1 to `(n*m)/2`, and each number appears exactly twice.
   - The task is to find the minimum number of movements required to make each pair of shoes adjacent.

2. **Key Insight**:
   - For each pair of shoes, we need to check if they are already adjacent. If they are, no movement is needed.
   - If they are not adjacent, we need to move one of the shoes to an adjacent cell. The optimal solution involves moving the shoe to the closest adjacent cell such that the total number of movements is minimized.

3. **Algorithm**:
   - **Check Adjacency**: For each pair of shoes, check if they are already adjacent. If they are, no movement is needed.
   - **Find Closest Adjacent Cell**: If they are not adjacent, find the closest adjacent cell to one of the shoes where the other shoe can be moved. This involves checking all adjacent cells and calculating the Manhattan distance to the other shoe's position.
   - **Count Movements**: Sum the movements required for all pairs that are not initially adjacent.

### Solution Code
```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <climits>
#include <algorithm>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> grid(n, vector<int>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> grid[i][j];
        }
    }

    vector<pair<int, int>> positions((n * m) / 2 + 1);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int val = grid[i][j];
            if (positions[val].first == -1) {
                positions[val] = {i, j};
            } else {
                positions[val].second = i * m + j;
            }
        }
    }

    int total = 0;
    for (int k = 1; k <= (n * m) / 2; ++k) {
        int x1 = positions[k].first;
        int y1 = positions[k].second % m;
        int x2 = positions[k].second / m;
        int y2 = positions[k].second % m;

        if (abs(x1 - x2) + abs(y1 - y2) == 1) {
            continue;
        }

        int min_dist = INT_MAX;
        for (int dx = -1; dx <= 1; ++dx) {
            for (int dy = -1; dy <= 1; ++dy) {
                if (abs(dx) + abs(dy) != 1) continue;
                int nx = x1 + dx;
                int ny = y1 + dy;
                if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                    int dist = abs(nx - x2) + abs(ny - y2);
                    if (dist < min_dist) {
                        min_dist = dist;
                    }
                }
            }
        }

        total += min_dist;
    }

    cout << total << endl;
    return 0;
}
