### Explanation
1. **Reading Input**: The grid dimensions and shoe positions are read from the input.
2. **Tracking Positions**: For each shoe pair, the positions of the two shoes are stored.
3. **Checking Adjacency**: For each pair, we check if the shoes are already adjacent. If they are, no movement is needed.
4. **Calculating Minimum Movements**: If not adjacent, we check all adjacent cells to one shoe and calculate the Manhattan distance to the other shoe's position. The minimum distance found is added to the total movements.
5. **Output Result**: The total number of movements required is printed.

This approach efficiently determines the minimum movements by leveraging the Manhattan distance and checking all possible adjacent cells for optimal placement.

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <climits>
using namespace std;

typedef pair<int, int> pii;

const int INF = 1e9;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> grid(n, vector<int>(m));
    vector<pii> pos;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> grid[i][j];
            pos.push_back({i, j});
        }
    }

    int total = n * m;
    vector<vector<int>> dist(total, vector<int>(total, INF));
    for (int i = 0; i < total; i++) {
        dist[i][i] = 0;
    }

    vector<int> dx = {0, 0, 1, -1};
    vector<int> dy = {1, -1, 0, 0};

    for (int i = 0; i < total; i++) {
        int x = pos[i].first;
        int y = pos[i].second;
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                int j = nx * m + ny;
                dist[i][j] = 1;
            }
        }
    }

    for (int k = 0; k < total; k++) {
        for (int i = 0; i < total; i++) {
            for (int j = 0; j < total; j++) {
                if (dist[i][k] < INF && dist[k][j] < INF) {
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }
    }

    vector<vector<int>> pairs;
    vector<bool> used(total, false);
    for (int i = 0; i < total; i++) {
        if (used[i]) continue;
        for (int j = i + 1; j < total; j++) {
            if (grid[pos[i].first][pos[i].second] == grid[pos[j].first][pos[j].second]) {
                pairs.push_back({i, j});
                used[i] = true;
                used[j] = true;
                break;
            }
        }
    }

    int num_pairs = pairs.size();
    vector<vector<int>> cost(num_pairs, vector<int>(num_pairs, INF));
    for (int i = 0; i < num_pairs; i++) {
        for (int j = 0; j < num_pairs; j++) {
            if (i == j) continue;
            int a1 = pairs[i][0], a2 = pairs[i][1];
            int b1 = pairs[j][0], b2 = pairs[j][1];
            int c1 = dist[a1][b1] + dist[a2][b2];
            int c2 = dist[a1][b2] + dist[a2][b1];
            cost[i][j] = min(c1, c2);
        }
    }

    vector<vector<int>> dp(1 << num_pairs, vector<int>(num_pairs, INF));
    for (int i = 0; i < num_pairs; i++) {
        dp[1 << i][i] = 0;
    }

    for (int mask = 0; mask < (1 << num_pairs); mask++) {
        for (int last = 0; last < num_pairs; last++) {
            if (dp[mask][last] == INF) continue;
            for (int next = 0; next < num_pairs; next++) {
                if (mask & (1 << next)) continue;
                int new_mask = mask | (1 << next);
                dp[new_mask][next] = min(dp[new_mask][next], dp[mask][last] + cost[last][next]);
            }
        }
    }

    int ans = INF;
    for (int i = 0; i < num_pairs; i++) {
        ans = min(ans, dp[(1 << num_pairs) - 1][i]);
    }

    cout << ans << endl;
    return 0;
}
