#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

const int MAXN = 85;
int n, m;
int grid[MAXN][MAXN];
int pair_id[MAXN][MAXN];
int dist[MAXN][MAXN][2]; // 0: not paired, 1: paired
vector<pair<int, int> > positions[3500]; // max pairs is (80*80)/2 = 3200

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> grid[i][j];
            positions[grid[i][j]].push_back(make_pair(i, j));
        }
    }

    // Assign pair IDs
    int pair_count = 0;
    for (int i = 1; i <= n*m/2; i++) {
        if (positions[i].size() == 2) {
            pair_count++;
            pair_id[positions[i][0].first][positions[i][0].second] = pair_count;
            pair_id[positions[i][1].first][positions[i][1].second] = pair_count;
        }
    }

    // BFS to find minimum moves
    memset(dist, -1, sizeof(dist));
    queue<pair<pair<int, int>, int> > q;

    // Start from all positions, trying to pair them
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (dist[i][j][0] == -1) {
                dist[i][j][0] = 0;
                q.push(make_pair(make_pair(i, j), 0));
            }
        }
    }

    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};

    while (!q.empty()) {
        int x = q.front().first.first;
        int y = q.front().first.second;
        int state = q.front().second;
        q.pop();

        // Try moving to adjacent cells
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                if (state == 0) {
                    // Not yet paired, try to pair with adjacent
                    if (pair_id[x][y] == pair_id[nx][ny] && dist[nx][ny][1] == -1) {
                        dist[nx][ny][1] = dist[x][y][0] + 1;
                        q.push(make_pair(make_pair(nx, ny), 1));
                    }
                    if (dist[nx][ny][0] == -1) {
                        dist[nx][ny][0] = dist[x][y][0] + 1;
                        q.push(make_pair(make_pair(nx, ny), 0));
                    }
                } else {
                    // Already paired, just move
                    if (dist[nx][ny][1] == -1) {
                        dist[nx][ny][1] = dist[x][y][1] + 1;
                        q.push(make_pair(make_pair(nx, ny), 1));
                    }
                }
            }
        }
    }

    // Find minimum moves to pair all shoes
    int result = 0;
    for (int i = 1; i <= pair_count; i++) {
        int x1 = positions[i][0].first;
        int y1 = positions[i][0].second;
        int x2 = positions[i][1].first;
        int y2 = positions[i][1].second;

        // Check if already paired
        if (abs(x1 - x2) + abs(y1 - y2) == 1) {
            continue;
        }

        // Need to move one of them
        result += 2; // At least 2 moves needed (move one shoe to pair)
    }

    cout << result << endl;
    return 0;
}
