### Explanation
- **Reading Input**: The grid dimensions and elements are read first.
- **Tracking Positions**: A map is used where each key is a shoe number, and the value is a list of coordinates where that shoe is located.
- **Checking Adjacency**: For each shoe pair, we check if their coordinates are adjacent by calculating the Manhattan distance. If the distance is not 1, the pair is not adjacent, and we increment our move count.
- **Result**: The total count of non-adjacent pairs is printed, which is the minimum number of moves required to make all pairs adjacent.

This approach efficiently determines the minimum moves by leveraging the properties of adjacency and ensuring each move addresses exactly one non-adjacent pair. The complexity is linear with respect to the number of cells, making it suitable for the given problem constraints.

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

const int MAXN = 85;
const int MAXM = 85;
const int MAXNUM = MAXN * MAXM;

int n, m;
int grid[MAXN][MAXM];
int pairX[MAXNUM], pairY[MAXNUM];
int dist[MAXN][MAXM];

int dx[] = {0, 0, 1, -1};
int dy[] = {1, -1, 0, 0};

bool bfs(int srcX, int srcY, int destX, int destY) {
    memset(dist, -1, sizeof(dist));
    queue<pair<int, int>> q;
    q.push({srcX, srcY});
    dist[srcX][srcY] = 0;

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        if (x == destX && y == destY) return true;

        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (nx >= 0 && nx < n && ny >= 0 && ny < m && dist[nx][ny] == -1) {
                dist[nx][ny] = dist[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    return false;
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> grid[i][j];
            if (pairX[grid[i][j]] == 0) {
                pairX[grid[i][j]] = i;
                pairY[grid[i][j]] = j;
            } else {
                pairX[grid[i][j]] = -1; // mark as having two positions
            }
        }
    }

    vector<pair<int, int>> pairs;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int num = grid[i][j];
            if (pairX[num] == -1) {
                // Find the other position
                for (int x = 0; x < n; x++) {
                    for (int y = 0; y < m; y++) {
                        if (grid[x][y] == num && (x != i || y != j)) {
                            pairs.push_back({i * m + j, x * m + y});
                            pairX[num] = -2; // mark as processed
                            break;
                        }
                    }
                    if (pairX[num] == -2) break;
                }
            }
        }
    }

    int total = 0;
    for (auto& p : pairs) {
        int x1 = p.first / m, y1 = p.first % m;
        int x2 = p.second / m, y2 = p.second % m;

        if (abs(x1 - x2) + abs(y1 - y2) == 1) {
            continue; // already together
        }

        // Try to find a path for one shoe to be adjacent to the other
        bool found = false;
        for (int i = 0; i < 4; i++) {
            int nx = x2 + dx[i];
            int ny = y2 + dy[i];

            if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                if (bfs(x1, y1, nx, ny)) {
                    found = true;
                    break;
                }
            }
        }

        if (!found) {
            for (int i = 0; i < 4; i++) {
                int nx = x1 + dx[i];
                int ny = y1 + dy[i];

                if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                    if (bfs(x2, y2, nx, ny)) {
                        found = true;
                        break;
                    }
                }
            }
        }

        if (found) {
            total++;
        } else {
            total += 2;
        }
    }

    cout << total << endl;
    return 0;
}
